settings.css:
body{background-color:rgba(0,0,0,0);margin:0;overflow:hidden} /* Chat des lives linedev (page dock.html de Social Stream Ninja, CSS posé dans la source OBS par obs/generer.mjs).
   Même règles que chat-latshow.css, aux couleurs de linedev : sur le papier, texte encre, pseudo vermillon,
   JetBrains Mono un peu plus petit (police à chasse fixe, plus large). */
@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;700&display=swap');
#menu,#context-menu{display:none!important}
html,body,#output{background:transparent!important}
#output{left:0!important;right:0!important;width:auto!important;box-sizing:border-box!important;padding:0 12px 10px!important}
.highlight-chat{background:transparent!important;border:0!important;box-shadow:none!important;padding:2px 0!important;margin:0!important}
.hl-message{display:block!important;font:400 12px/1.4 'JetBrains Mono',monospace!important;color:#14130F!important;text-shadow:none!important;-webkit-text-stroke:0!important;letter-spacing:0!important;text-indent:0!important;padding:0!important;margin:0!important;overflow:visible!important}
.hl-source-type{width:11px!important;height:11px!important;vertical-align:-2px!important;margin:0 6px 0 0!important;opacity:.9}
.hl-name{display:inline!important;font:700 12px/1.4 'JetBrains Mono',monospace!important;color:#C93A12!important;margin-right:6px!important;text-shadow:none!important;-webkit-text-stroke:0!important}
.hl-content{display:inline!important;font:400 12px/1.4 'JetBrains Mono',monospace!important;color:#14130F!important;text-shadow:none!important;-webkit-text-stroke:0!important}

